from pathlib import Path
import re, json, html, mistune
from bs4 import BeautifulSoup
root=Path(__file__).resolve().parent; out=root.parent
esc=html.escape
md=mistune.create_markdown(escape=False,plugins=['table'])
def cards(items,cls='cards',caption=''):
 return f'<div class="{cls}">'+''.join(f'<div class="tile"><strong>{esc(a)}</strong><p>{esc(b)}</p></div>' for a,b in items)+'</div>'+(f'<div class="figcaption">{esc(caption)}</div>' if caption else '')
def bars(items,caption=''):
 return '<div class="bars">'+''.join(f'<div class="baritem"><div><span>{esc(a)}</span><strong>{v}%</strong></div><div class="track"><span style="width:{v}%"></span></div></div>' for a,v in items)+'</div>'+(f'<p class="figcaption">{esc(caption)}</p>' if caption else '')
def steps(items,title=''):
 return (f'<h4>{esc(title)}</h4>' if title else '')+'<div class="steps">'+''.join(f'<div class="step"><span class="stepnum">{i+1:02}</span><div><strong>{esc(a)}</strong>{f"<p>{esc(b)}</p>" if b else ""}</div></div>' for i,(a,b) in enumerate(items))+'</div>'
def node(a,b='',href='',cls=''):
 tag='a' if href else 'div'; return f'<{tag} class="node {cls}"'+(f' href="{href}"' if href else '')+f'><strong>{esc(a)}</strong><small>{esc(b)}</small></{tag}>'
def ecosystem(link=False):
 l=lambda x:f'#p2/m5-{x}' if link else ''
 return '<div class="diagram">'+node('ORGANIC VIỆT NAM','Chiến lược · Đầu tư · Quản trị · Phát triển',l(1),'dark')+'<div class="connector">↓</div><div class="diagram-row three">'+node('ORGANIC FARM','Nông nghiệp · Nguồn nguyên liệu',l(2))+node('ORGANIC FOOD','Thực phẩm · Giá trị sản phẩm',l(3))+node('ORGANIC DISTRIBUTION','Chuỗi cung ứng · Lưu chuyển hàng hóa',l(4))+'</div><div class="connector">↓</div>'+node('ADIGO','Nền tảng công nghệ quản trị và thương mại · Dữ liệu · Vận hành · Truy xuất · Kết nối thị trường',l(5),'blue')+'<div class="connector">↓</div><div class="diagram-row two">'+node('ADIGO MART','Bán lẻ & trải nghiệm',l(6),'lightblue')+node('ADIGO MARKETPLACE','Kết nối thương mại số',l(7),'lightblue')+'</div><div class="connector">↓</div>'+node('CUSTOMER','Người tiêu dùng · Khách hàng · Đối tác','','dark')+node('DOANH THU · DỮ LIỆU · PHẢN HỒI · TĂNG TRƯỞNG','Hệ sinh thái mở rộng thông qua nhà cung cấp và đối tác',l(8))+'</div><p class="figcaption">Kiến trúc hệ sinh thái Organic Việt Nam – Mô hình định hướng chiến lược 2027–2029</p>'
