source=(root/'strategy.md').read_text(); chunks=re.split(r'<!-- PART:(\d+) -->',source); intro=md(chunks[0]); sections=[]; projects=[]; search=[]
for i in range(1,len(chunks),2):
 p=int(chunks[i]); raw=chunks[i+1]; rendered=md(raw)
 for w in re.findall(r'<!-- WIDGET:(\w+) -->',rendered): rendered=rendered.replace(f'<!-- WIDGET:{w} -->',f'<div class="visual">{widgets[w]}</div>')
 soup=BeautifulSoup(rendered,'html.parser'); title=soup.h1.get_text(); soup.h1.extract()
 headings=[]
 for h in soup.find_all(['h2','h3']):
  m=re.match(r'([0-9]+(?:\.[0-9]+)*)\.',h.get_text())
  # subheads e.g. 5.1. or 14.1. match greedily
  if m:
   ident='m'+m.group(1).replace('.','-'); h['id']=ident; headings.append({'id':ident,'title':h.get_text(),'level':int(h.name[1])})
 for table in soup.find_all('table'):
  if p==10:
   for tr in table.find_all('tr'):
    cells=[td.get_text(' ',strip=True) for td in tr.find_all('td')]
    if cells and re.fullmatch(r'[A-F]\d\d',cells[0]):
     projects.append(dict(zip(['id','name','priority','schedule'],cells))); tr['id']='project-'+cells[0]
  wrapper=soup.new_tag('div',attrs={'class':'table-scroll'}); table.wrap(wrapper)
 # search index: full section including widget content
 for idx,h in enumerate(soup.find_all('h2')):
  block=[]
  for sib in h.next_siblings:
   if getattr(sib,'name',None)=='h2': break
   block.append(sib.get_text(' ',strip=True) if hasattr(sib,'get_text') else str(sib))
  search.append({'p':p,'id':h.get('id',''),'title':h.get_text(),'body':' '.join(block)})
 if p==13: search.append({'p':p,'id':'','title':title,'body':soup.get_text(' ',strip=True)})
 sections.append({'p':p,'title':title,'html':str(soup),'headings':headings})
assert len(projects)==57, len(projects)
assert sum(len([h for h in s['headings'] if h['level']==2]) for s in sections)==50
(root/'data.json').write_text(json.dumps({'sections':sections,'intro':intro,'projects':projects,'search':search,'budgetnames':budgetnames,'weights':weights},ensure_ascii=False))
